const strip = s => (s || '').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();

const allItems = $input.all();
console.log('Total items from RemoteOK:', allItems.length);

const jobs = allItems
  .map(item => item.json)
  .filter(j => j && j.position)
  .map(j => ({
    title: j.position || '',
    company: j.company || 'Unknown',
    location: 'Remote',
    salary_min: j.salary_min ? parseInt(j.salary_min) : 0,
    salary_max: j.salary_max ? parseInt(j.salary_max) : 0,
    description: strip(j.description || '').substring(0, 1500),
    url: j.url || '',
    apply_url: j.apply_url || j.url || '',
    tags: (j.tags || []).join(', '),
    created: j.date || '',
    source: 'RemoteOK'
  }));

const seen = new Set();
const unique = jobs.filter(j => {
  if (!j.url || seen.has(j.url)) return false;
  seen.add(j.url);
  return true;
});

console.log(`RemoteOK jobs: ${unique.length}`);
return unique.map(j => ({ json: j }));

const strip = s => (s || '').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();

const allItems = $input.all();
console.log('Total items from WWR RSS:', allItems.length);

const jobs = allItems
  .map(item => item.json)
  .filter(j => j && j.title)
  .map(j => {
    const titleRaw = j.title || '';
    const colonIdx = titleRaw.indexOf(': ');
    let company = 'Unknown';
    let title = titleRaw;
    if (colonIdx > 0) {
      company = titleRaw.substring(0, colonIdx).trim();
      title = titleRaw.substring(colonIdx + 2).trim();
    }
    // WWR RSS: link points to weworkremotely.com job page.
    // apply_url is often in enclosure[0].url or can be extracted from content.
    // We store platform url separately and expose apply_url when available.
    const platformUrl = j.link || j.guid || '';
    const applyUrl = j.enclosure?.url || j['enclosure:url'] || platformUrl;
    return {
      title: title,
      company: company,
      location: 'Remote',
      salary_min: 0,
      salary_max: 0,
      description: strip(j.contentSnippet || j.content || j.description || '').substring(0, 1500),
      url: platformUrl,
      apply_url: applyUrl,
      tags: '',
      created: j.pubDate || j.isoDate || '',
      source: 'WeWorkRemotely'
    };
  })
  .filter(j => j.url);

const seen = new Set();
const unique = jobs.filter(j => {
  if (seen.has(j.url)) return false;
  seen.add(j.url);
  return true;
});

console.log(`WWR jobs: ${unique.length}`);
return unique.map(j => ({ json: j }));

