const seenRows = $('🗄️ Get Seen URLs').all();
const seenUrls = new Set(seenRows.map(item => item.json.url).filter(Boolean));

const allItemsRaw = $('🔀 Merge All Sources').all();

if (allItemsRaw.length === 1 && allItemsRaw[0].json._error) {
  return [allItemsRaw[0]];
}

const newJobs = allItemsRaw.filter(item => {
  const url = item.json.url;
  return url && !seenUrls.has(url);
});

const bySource = {};
newJobs.forEach(item => {
  const src = item.json.source || 'Unknown';
  bySource[src] = (bySource[src] || 0) + 1;
});
console.log(`Total: ${allItemsRaw.length} | New: ${newJobs.length} | Already seen: ${allItemsRaw.length - newJobs.length}`);
console.log('New by source:', JSON.stringify(bySource));

if (newJobs.length === 0) {
  return [{ json: { _noNewJobs: true } }];
}

return newJobs;

const real = $input.all().filter(item => !!item.json.url);

if (real.length === 0) {
  return [{ json: { _noNewJobs: true } }];
}

return real.map(item => ({ json: { ...item.json, _noNewJobs: false } }));

const raw = $input.item.json;
const itemIndex = $itemIndex;

let ai;
try {
  const txt = raw.choices?.[0]?.message?.content || '{}';
  ai = JSON.parse(txt.replace(/```json|```/g, '').trim());
} catch(e) {
  console.log('Failed to parse DeepSeek response:', e.message);
  ai = { score: 0, verdict: 'NOT_AI', reason_ru: 'Ошибка оценки', ai_tools: [], ai_feasible: false, automation_percent: 0 };
}

let job;
try {
  job = $('🆕 Has New Jobs?').itemMatching(itemIndex).json;
} catch(e) {
  const allFromHasNewJobs = $('🆕 Has New Jobs?').all();
  if (allFromHasNewJobs[itemIndex]) {
    job = allFromHasNewJobs[itemIndex].json;
  } else {
    return [];
  }
}

const feasible = ai.ai_feasible === true || ai.ai_feasible === 'true';
const autoPct = parseInt(ai.automation_percent) || 0;

console.log(`[${itemIndex}] "${job.title}" [${job.source}] -> feasible=${feasible}, autoPct=${autoPct}`);

return [{ json: {
  title: job.title,
  company: job.company,
  location: job.location,
  salary_min: job.salary_min,
  salary_max: job.salary_max,
  description: job.description,
  url: job.url,
  apply_url: job.apply_url || job.url,
  tags: job.tags,
  created: job.created,
  source: job.source || 'Unknown',
  ai_score: parseInt(ai.score) || 0,
  ai_verdict: ai.verdict || 'NOT_AI',
  ai_feasible: feasible,
  automation_percent: autoPct,
  ai_tools: ai.ai_tools || [],
  reason_ru: ai.reason_ru || ''
}}];

return $input.all().filter(item => {
  const j = item.json;
  const feasible = j.ai_feasible === true;
  const pct = Number(j.automation_percent) || 0;
  const pass = feasible && pct >= 50;
  if (!pass) console.log(`Отфильтровано: "${j.title}" feasible=${feasible} pct=${pct}`);
  return pass;
});

const job = $json;
const score = job.automation_percent || 0;

let color;
if (score >= 90) color = 15844367;
else if (score >= 80) color = 5763719;
else if (score >= 70) color = 16776960;
else color = 3447003;

const verdictMap = {
  'GREAT_FIT': '🏆 GREAT FIT',
  'GOOD_FIT': '✅ GOOD FIT',
  'POSSIBLE_FIT': '🔄 POSSIBLE FIT',
  'NOT_SUITABLE': '❌ NOT SUITABLE'
};

let salaryStr = 'Не указана';
if (job.salary_min > 0 && job.salary_max > 0)
  salaryStr = `$${Math.round(job.salary_min/1000)}k – $${Math.round(job.salary_max/1000)}k`;
else if (job.salary_min > 0)
  salaryStr = `от $${Math.round(job.salary_min/1000)}k`;

const sourceEmoji = { 'RemoteOK': '🟢', 'WeWorkRemotely': '🔵', 'NoDesk': '🟣', 'Arbeitnow': '🟠', 'Remotive': '🟡', 'Jobicy': '🔴', 'Himalayas': '⚪', 'Adzuna': '🟤', 'Jooble': '🔷' };
const srcLabel = `${sourceEmoji[job.source] || '⚫'} ${job.source || 'Unknown'}`;

const toolsList = (job.ai_tools || []).slice(0, 5).map(t => `✓ ${t}`).join('\n') || '—';
const analysis = (job.reason_ru || '—').substring(0, 1024);

// apply_url = direct link to company/apply page
// url = platform page (used as embed URL for Discord preview)
const applyUrl = job.apply_url || job.url;
const platformUrl = job.url;
const applyDisplay = applyUrl !== platformUrl
  ? `[Откликнуться напрямую](${applyUrl})\n[Страница на платформе](${platformUrl})`
  : `[Открыть вакансию](${applyUrl})`;

const embed = {
  title: job.title.substring(0, 256),
  url: platformUrl,
  color: color,
  fields: [
    { name: '🤖 AI Автоматизация', value: `${score}%  •  ${verdictMap[job.ai_verdict] || '⚡'}`, inline: true },
    { name: '🏢 Компания', value: (job.company || '—').substring(0, 100), inline: true },
    { name: '📌 Источник', value: srcLabel, inline: true },
    { name: '💰 Зарплата', value: salaryStr, inline: true },
    { name: '🛠 AI инструменты', value: toolsList.substring(0, 1024), inline: false },
    { name: '💡 Анализ', value: analysis, inline: false },
    { name: '🔗 Ссылки', value: applyDisplay.substring(0, 500), inline: false }
  ],
  footer: { text: `Анализ выполнен AI • ${new Date().toLocaleDateString('ru-RU')}` }
};

return [{ json: { ...job, discord_embed: embed } }];

