const junkPatterns = /future consideration|talent pool|resume database|general application|keep (your |)resume on file|various positions|open application|all other/i;

const physicalPatterns = /in-store|on-the-floor|back of house|warehouse|stockroom|retail store|shift work|on-site|onsite|physical presence|point of sale|till work/i;

const remoteSignals = /\bremote\b|work from home|\bwfh\b|anywhere|worldwide|distributed team|удал[её]нн?о/i;

const out = [];
for (const item of $input.all()) {
  const job = item.json;
  const title = job.title || '';
  const desc = job.description || '';
  const text = `${title} ${desc}`;

  const looksGeneric = junkPatterns.test(text);
  const tooShort = desc.replace(/\s+/g, ' ').trim().length < 150;
  const looksPhysical = physicalPatterns.test(text);
  const hasRemoteSignal = remoteSignals.test(text);

  if (looksGeneric || tooShort || looksPhysical || !hasRemoteSignal) {
    console.log(`Пропущено: "${title}" (generic=${looksGeneric}, short=${tooShort}, physical=${looksPhysical}, noRemoteSignal=${!hasRemoteSignal})`);
    continue;
  }
  out.push(item);
}
return out;

const staticData = $getWorkflowStaticData('global');
const now = Date.now();
const maxLockMs = 30 * 60 * 1000; // страховка на случай, если release почему-то не выполнится

if (staticData.lockUntil && staticData.lockUntil > now) {
  console.log('Предыдущий запуск ещё выполняется — пропускаю этот триггер.');
  return [];
}

staticData.lockUntil = now + maxLockMs;
return [{ json: { _lockAcquired: true } }];

const staticData = $getWorkflowStaticData('global');
delete staticData.lockUntil;
console.log('Лок снят.');
return [{ json: { _released: true } }];

